package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.exception.BusinessException;import com.sunrise.dentalclinic.model.AppointmentStatus;import com.sunrise.dentalclinic.repository.*;import com.sunrise.dentalclinic.service.DentistService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.time.*;
@Controller @RequestMapping("/reports") public class ReportController{private final AppointmentRepository appointments;private final BillRepository bills;private final DentistService dentists;public ReportController(AppointmentRepository a,BillRepository b,DentistService d){appointments=a;bills=b;dentists=d;}@GetMapping String report(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)Long dentistId,@RequestParam(required=false)AppointmentStatus status,Model m){if(from==null)from=LocalDate.now();if(to==null)to=from;if(to.isBefore(from))throw new BusinessException("End date must not be before start date");m.addAttribute("appointments",appointments.report(from,to,dentistId,status));m.addAttribute("revenue",bills.revenue(from.atStartOfDay(),to.plusDays(1).atStartOfDay()));m.addAttribute("dentists",dentists.all());m.addAttribute("statuses",AppointmentStatus.values());m.addAttribute("from",from);m.addAttribute("to",to);return "reports/index";}}
